function brandAirtable({name, logos}) {
  if (typeof name !== 'string' || !name.trim() || !Array.isArray(logos)) throw new Error('Brand name and logo assets are required');
  function validUrl(value) {
    if (typeof value !== 'string' || /[\s\x00-\x1f\x7f\\]/.test(value) || /%(?![0-9a-f]{2})/i.test(value)) return false;
    const match = /^https?:\/\/([^/?#]+)(?:[/?#].*)?$/i.exec(value);
    if (!match || match[1].includes('@')) return false;
    const authority = match[1];
    let host, port;
    if (authority.startsWith('[')) {
      const parts = /^\[([0-9a-f:]+)\](?::(\d+))?$/i.exec(authority);
      if (!parts) return false;
      host = parts[1]; port = parts[2];
      const halves = host.split('::');
      if (halves.length > 2) return false;
      const groups = halves.flatMap(part => part ? part.split(':') : []);
      if (groups.some(group => !/^[0-9a-f]{1,4}$/i.test(group))) return false;
      if (halves.length === 1 ? groups.length !== 8 : groups.length >= 8) return false;
    } else {
      const parts = /^([^:]+)(?::(\d+))?$/.exec(authority);
      if (!parts) return false;
      host = parts[1]; port = parts[2];
      if (host.length > 253) return false;
      const labels = host.replace(/\.$/, '').split('.');
      if (!labels.every(label => label.length > 0 && label.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label))) return false;
      if (labels.every(label => /^\d+$/.test(label)) && (labels.length !== 4 || labels.some(label => Number(label) > 255))) return false;
    }
    return port === undefined || (port.length <= 5 && Number(port) <= 65535);
  }
  function asset(type) {
    for (const logo of logos) {
      if (logo?.type !== type || !Array.isArray(logo.formats)) continue;
      for (const format of logo.formats) {
        if (validUrl(format?.src)) return format.src;
      }
    }
    throw new Error(`No usable ${type} URL returned by Brandfetch`);
  }
  return {records:[{fields:{Name:name,'Icon URL':asset('icon'),'Logo URL':asset('logo')}}]};
}

return {json:brandAirtable({name:$json.name,logos:$json.logos}).records[0].fields};
